<script lang="ts">
  import JavaRuntimeIcon from "./JavaRuntimeIcon.svelte";
  import GameIcon from "./GameIcon.svelte";
  import ServiceLogo from "./ServiceLogo.svelte";
  import BrandWordmark from './BrandWordmark.svelte';
  import LauncherDisplaySettings from './LauncherDisplaySettings.svelte';
  import LegalNotice from './LegalNotice.svelte';
  import UiIcon from './UiIcon.svelte';
  import { LANGUAGES, detectSystemLanguage, setLocale, t } from './i18n';
  import type { LauncherSettings, AppearanceSettings, ThemePreset, JavaRuntime, AccountSummary, QuickFolder, SettingsTab, Result } from './settings.types';

  let {
    settings, onchange, appearance, onappearance, themes, runtimes = [], accounts = [], offlineAllowed=false,offlineMessage="",
    secretsFound = 0, secretsTotal = 1000, initialTab = 'general', totalMemoryGb = 16,
    onrepeatwizard, onscanjava, oninstalljava, ontogglejava, ontestjava, onaddmicrosoft,
    onaddoffline, onactivateaccount, onremoveaccount, onopenfolder, onpickicon, onremoveicon,
    iconPreview = '', iconMessage = '', oncheckupdates
  }: {
    settings: LauncherSettings; onchange: (patch: Partial<LauncherSettings>) => Result;
    appearance: AppearanceSettings; onappearance: (patch: Partial<AppearanceSettings>) => Result;
    themes: ThemePreset[]; runtimes?: JavaRuntime[]; accounts?: AccountSummary[];offlineAllowed?:boolean;offlineMessage?:string;
    secretsFound?: number; secretsTotal?: number; initialTab?: SettingsTab; totalMemoryGb?: number;
    onrepeatwizard: () => Result; onscanjava: () => Result; oninstalljava: (major: number) => Result;
    ontogglejava: (major: number, enabled: boolean) => Result; ontestjava: (path: string) => Result;
    onaddmicrosoft: () => Result; onaddoffline: (name: string) => Result;
    onactivateaccount: (id: string) => Result; onremoveaccount: (id: string) => Result;
    onopenfolder: (folder: QuickFolder) => Result; onpickicon?: (event: Event) => Result; onremoveicon?: () => Result;
    iconPreview?: string; iconMessage?: string; oncheckupdates?: () => Result;
  } = $props();
  let tab = $state<SettingsTab>('general');
  let search = $state('');
  let message = $state('');
  let failed = $state(false);
  let busy = $state('');
  let dataRoot = $state('');
  let offlineName = $state('');
  let addOffline = $state(false);
  let removeId = $state('');
  let javaPath = $state('');
  let applicationId = $state('');
  $effect(() => { tab = initialTab; });
  $effect(() => { dataRoot = settings.data_root; });
  $effect(() => { applicationId = settings.discord_application_id; });
  const tabs: { id: SettingsTab; name: string; icon: string }[] = [
    { id: 'general', name: 'General', icon: 'settings' }, { id: 'display', name: 'Pantalla', icon: 'grid' }, { id: 'language', name: 'Idioma', icon: 'grid' },
    { id: 'appearance', name: 'Apariencia', icon: 'image' }, { id: 'minecraft', name: 'Minecraft', icon: 'cube' },
    { id: 'java', name: 'Java', icon: 'terminal' }, { id: 'accounts', name: 'Cuentas', icon: 'user' }
  ];
  let filteredLanguages = $derived(LANGUAGES.filter((language) => `${language.name} ${language.region} ${language.code}`.toLocaleLowerCase().includes(search.trim().toLocaleLowerCase())));
  let runtimeRows = $derived.by(() => {
    const majors = new Set([8, 17, 21, 22, 25, ...runtimes.map((runtime) => runtime.major)]);
    return [...majors].sort((a, b) => a - b).map((major) => runtimes.find((runtime) => runtime.major === major) ?? { major, installed: false, enabled: true, path: '' });
  });
  let memoryLimit = $derived(Math.max(2, Math.min(128, Math.floor(totalMemoryGb || 16))));
  async function perform(key: string, action: () => Result, fallback = 'Cambios guardados') {
    if (busy) return;
    busy = key; message = ''; failed = false;
    try { const result = await action(); message = typeof result === 'string' && result ? result : $t(fallback); }
    catch (error) { failed = true; message = String(error); }
    finally { busy = ''; }
  }
  async function change(patch: Partial<LauncherSettings>) {
    try { await onchange(patch); }
    catch (error) { failed = true; message = String(error); }
  }
  async function changeAppearance(patch: Partial<AppearanceSettings>) {
    try { await onappearance(patch); }
    catch (error) { failed = true; message = String(error); }
  }
  async function changeLanguage(code: string) { setLocale(code); await change({ language: code }); }
  function chooseTheme(theme: ThemePreset) {
    void changeAppearance({ selectedThemeId: theme.id, ...(theme.id === 'custom' ? {} : { primaryColor: theme.primary, secondaryColor: theme.secondary, bgBaseColor: theme.bgBase }) });
  }
  function transparency(mode: AppearanceSettings['transparencyPreset']) {
    const profiles = { fantasma: [.55, .35, .45, .30, 22], equilibrado: [.85, .72, .80, .60, 14], lectura: [.94, .88, .92, .82, 8], solido: [1, 1, 1, .98, 0] };
    const [bgOpacity, menuOpacity, barOpacity, cardOpacity, blurPx] = profiles[mode];
    void changeAppearance({ transparencyPreset: mode, bgOpacity, menuOpacity, barOpacity, cardOpacity, blurPx });
  }
  async function pickBackground(event: Event) {
    const input = event.currentTarget as HTMLInputElement;
    const file = input.files?.[0];
    if (!file) return;
    if (!/^image\/(png|jpeg|webp)$/.test(file.type) || file.size > 12 * 1024 * 1024) {
      failed = true; message = $t('Usa una imagen PNG, JPG o WebP de hasta 12 MB.'); input.value = ''; return;
    }
    const reader = new FileReader();
    reader.onload = () => { if (typeof reader.result === 'string') void changeAppearance({ backgroundUrl: reader.result }); };
    reader.onerror = () => { failed = true; message = $t('No se pudo leer la imagen.'); };
    reader.readAsDataURL(file); input.value = '';
  }
  async function createOffline() {
    if(!offlineAllowed){message=offlineMessage;failed=true;return;}
    const name = offlineName.trim();
    if (!/^[A-Za-z0-9_]{3,16}$/.test(name)) { failed = true; message = $t('Usa entre 3 y 16 letras, números o guiones bajos.'); return; }
    await perform('offline', () => onaddoffline(name));
    if (!failed) { offlineName = ''; addOffline = false; }
  }
</script>

<section class="settings-suite">
  <header class="suite-heading"><div><span class="eyebrow"><BrandWordmark/></span><h2><GameIcon name="redstone" size={25}/>{$t('Personaliza tu experiencia')}</h2><p>{$t('Preferencias del launcher, el juego y tus cuentas.')}</p></div><span class="autosave"><UiIcon name="settings" size={15} />{$t('La configuración se guarda automáticamente.')}</span></header>
  <nav class="settings-nav" aria-label={$t('Ajustes')}>
    {#each tabs as item}<button class:active={tab === item.id} aria-current={tab === item.id ? 'page' : undefined} onclick={() => { tab = item.id; message = ''; }}><UiIcon name={item.icon} size={17} />{$t(item.name)}</button>{/each}
  </nav>
  {#if message}<div class="status" class:failed role="status" data-diagnostic>{message}</div>{/if}

  {#if tab === 'general'}
    <div class="two-columns">
      <section class="surface"><h3><UiIcon name="play" />{$t('Comportamiento al iniciar Minecraft')}</h3><p>{$t('Elige cómo se comporta la ventana del launcher cuando abres un juego.')}</p><label for="launch-behavior">{$t('Comportamiento al iniciar Minecraft')}</label><select id="launch-behavior" value={settings.launch_behavior} onchange={(event) => change({ launch_behavior: event.currentTarget.value as LauncherSettings['launch_behavior'] })}><option value="keep">{$t('Mantener launcher abierto')}</option><option value="minimize">{$t('Minimizar ventana')}</option><option value="tray">{$t('Minimizar a la bandeja')}</option><option value="close">{$t('Cerrar launcher')}</option></select><small>{$t('Los registros de Minecraft se conservan en disco.')}</small></section>
      <section class="surface"><h3><UiIcon name="folder" />{$t('Carpeta raíz de datos')}</h3><p>{$t('Versiones, runtimes, instancias y archivos del launcher.')}</p><label for="data-root">{$t('Carpeta raíz de datos')}</label><div class="input-actions"><input id="data-root" bind:value={dataRoot} spellcheck="false" data-no-translate /><button disabled={!!busy || dataRoot.trim() === settings.data_root || !dataRoot.trim()} onclick={() => perform('folder', () => onchange({ data_root: dataRoot.trim() }))}><UiIcon name="folder" size={15}/>{$t('Aplicar carpeta')}</button></div><button class="link-action" onclick={() => perform('open-root', () => onopenfolder('root'), 'Listo')}><UiIcon name="folder" size={15} />{$t('Abrir ubicación')}</button></section>
    </div>
    <section class="surface"><h3><UiIcon name="settings" />{$t('Integraciones y actualizaciones')}</h3><div class="setting-row"><div><strong class="setting-brand"><ServiceLogo name="discord" size={19}/>{$t('Discord Rich Presence')}</strong><small>{$t('Compartir el estado del juego en Discord')}</small></div><label class="toggle"><input type="checkbox" checked={settings.discord_presence} onchange={(event) => change({ discord_presence: event.currentTarget.checked })} aria-label={$t('Discord Rich Presence')} /><span></span></label></div><div class="discord-id"><label for="discord-id">{$t('ID de aplicación de Discord')}</label><div class="input-actions"><input id="discord-id" bind:value={applicationId} placeholder="Application ID" inputmode="numeric" data-no-translate /><button disabled={!!busy || applicationId === settings.discord_application_id || (!!applicationId && !/^\d{15,22}$/.test(applicationId))} onclick={() => perform('discord', () => onchange({ discord_application_id: applicationId.trim() }))}><UiIcon name="save" size={15}/>{$t('Guardar')}</button></div><small>{$t('Usa el ID de tu aplicación de Discord para publicar la actividad.')}</small></div><div class="setting-row"><div><strong>{$t('Actualizaciones automáticas')}</strong><small>{$t('Buscar actualizaciones al abrir el launcher')}</small></div><label class="toggle"><input type="checkbox" checked={settings.automatic_updates} onchange={(event) => change({ automatic_updates: event.currentTarget.checked })} aria-label={$t('Actualizaciones automáticas')} /><span></span></label></div>{#if oncheckupdates}<button disabled={!!busy} onclick={() => perform('updates', () => oncheckupdates!(), 'Listo')}><UiIcon name="refresh" size={16} />{$t('Revisar actualizaciones')}</button>{/if}</section>
    <div class="two-columns"><section class="surface secrets"><div><span class="eyebrow">{$t('Secretos descubiertos')}</span><strong data-no-translate>{Math.min(secretsFound, secretsTotal).toLocaleString()} <span>/ {secretsTotal.toLocaleString()}</span></strong></div><div class="progress"><span style:width={`${Math.min(100, secretsFound / Math.max(1, secretsTotal) * 100)}%`}></span></div><small>{$t('Hay historias que solo aparecen cuando menos las esperas.')}</small></section><section class="surface"><h3><UiIcon name="info"/>{$t('Asistente de bienvenida')}</h3><p>{$t('Revisa tu idioma, memoria, motores Java y apariencia en tres pasos.')}</p><button onclick={() => onrepeatwizard()}><UiIcon name="refresh" size={16} />{$t('Repetir asistente de bienvenida')}</button></section></div>
  {:else if tab === 'display'}
    <LauncherDisplaySettings {settings} {onchange}/>
  {:else if tab === 'language'}
    <section class="surface"><div class="section-title"><div><h3><UiIcon name="globe"/>{$t('Idioma de la interfaz')}</h3><p>{$t('Cobertura del catálogo traducible. Los textos pendientes se muestran en español.')}</p></div><button onclick={() => changeLanguage(detectSystemLanguage())}><UiIcon name="refresh" size={16} />{$t('Detectar idioma del sistema')}</button></div><input class="language-search" type="search" bind:value={search} placeholder={$t('Buscar idioma o región…')} aria-label={$t('Buscar idioma o región…')} />
      <div class="table-wrap"><table><thead><tr><th>{$t('Idioma')}</th><th>{$t('Región / Código')}</th><th>{$t('Completado')}</th><th><span class="sr-only">{$t('Seleccionar')}</span></th></tr></thead><tbody>{#each filteredLanguages as language}<tr class:selected={settings.language === language.code}><td><strong data-no-translate>{language.name}</strong></td><td data-no-translate>{language.region}<code>{language.code}</code></td><td><div class="coverage"><div class="progress"><span style:width={`${language.completed}%`}></span></div><strong>{language.completed}%</strong></div><small title={`${language.translated} / ${language.total}`}>{language.translated} / {language.total}</small></td><td><button class:chosen={settings.language === language.code} disabled={settings.language === language.code} onclick={() => changeLanguage(language.code)}><UiIcon name={settings.language===language.code?"check":"globe"} size={14}/>{$t(settings.language === language.code ? 'Activado' : 'Seleccionar')}</button></td></tr>{/each}</tbody></table>{#if !filteredLanguages.length}<p class="empty">{$t('Sin resultados')}</p>{/if}</div>
    </section>
  {:else if tab === 'appearance'}
    <section class="surface"><div class="section-title"><div><h3><UiIcon name="image"/>{$t('Galería de Temas Oficiales')}</h3><p>{$t('Paletas diseñadas para acompañar cada sesión.')}</p></div></div><div class="themes">{#each themes as theme}<button class="theme" class:selected={appearance.selectedThemeId === theme.id} style={`--theme-accent:${theme.id === 'custom' ? appearance.primaryColor : theme.primary};--theme-secondary:${theme.id === 'custom' ? appearance.secondaryColor : theme.secondary}`} onclick={() => chooseTheme(theme)}><UiIcon name="image" size={15}/><span>{$t(theme.name)}</span>{#if appearance.selectedThemeId === theme.id}<small>{$t('Activado')}</small>{/if}</button>{/each}</div></section>
    <section class="surface"><h3><UiIcon name="sliders"/>{$t('Colores personalizados')}</h3><div class="color-grid">{#each [{ key: 'primaryColor' as const, name: 'Acento principal' }, { key: 'secondaryColor' as const, name: 'Acento secundario' }, { key: 'bgBaseColor' as const, name: 'Fondo base' }] as color}<label class="color-input"><span>{$t(color.name)}</span><div><input type="color" value={appearance[color.key]} oninput={(event) => changeAppearance({ selectedThemeId: 'custom', [color.key]: event.currentTarget.value })} /><code data-no-translate>{appearance[color.key]}</code></div></label>{/each}</div></section>
    <section class="surface"><h3><UiIcon name="eye"/>{$t('Transparencia')}</h3><div class="segmented">{#each [{ id: 'fantasma' as const, name: 'Fantasma' }, { id: 'equilibrado' as const, name: 'Equilibrado' }, { id: 'lectura' as const, name: 'Lectura' }, { id: 'solido' as const, name: 'Sólido' }] as profile}<button class:selected={appearance.transparencyPreset === profile.id} onclick={() => transparency(profile.id)}><UiIcon name="eye" size={14}/>{$t(profile.name)}</button>{/each}</div><div class="sliders">{#each [{ key: 'bgOpacity' as const, name: 'Opacidad del fondo' }, { key: 'menuOpacity' as const, name: 'Opacidad del menú' }, { key: 'barOpacity' as const, name: 'Opacidad de barra' }, { key: 'cardOpacity' as const, name: 'Opacidad de tarjetas' }] as slider}<label><span>{$t(slider.name)}<strong>{Math.round(appearance[slider.key] * 100)}%</strong></span><input type="range" min="0.15" max="1" step="0.01" value={appearance[slider.key]} oninput={(event) => changeAppearance({ [slider.key]: +event.currentTarget.value })} /></label>{/each}<label><span>{$t('Desenfoque')}<strong>{appearance.blurPx} px</strong></span><input type="range" min="0" max="32" step="1" value={appearance.blurPx} oninput={(event) => changeAppearance({ blurPx: +event.currentTarget.value })} /></label></div></section>
    <div class="two-columns"><section class="surface"><h3><UiIcon name="image" />{$t('Fondo personalizado')}</h3>{#if appearance.backgroundUrl}<img class="background-preview" src={appearance.backgroundUrl} alt={$t('Vista previa')} />{/if}<div class="actions"><label class="file-button"><UiIcon name="image" size={16} />{$t('Elegir fondo')}<input type="file" accept="image/png,image/jpeg,image/webp" onchange={pickBackground} /></label>{#if appearance.backgroundUrl}<button onclick={() => changeAppearance({ backgroundUrl: '' })}><UiIcon name="trash" size={15}/>{$t('Quitar fondo')}</button>{/if}</div></section><section class="surface"><h3><UiIcon name="image"/>{$t('Logo personalizado')}</h3><div class="logo-row">{#if iconPreview}<img src={iconPreview} alt={$t('Vista previa')} />{:else}<img src="/logos/tp-launcher.svg" alt="Cubo TP de TP LAUNCHER" />{/if}<div><p>{$t('Se ajusta automáticamente a 128 × 128.')}</p><div class="actions">{#if onpickicon}<label class="file-button"><UiIcon name="image" size={16} />{$t('Elegir imagen')}<input type="file" accept="image/png,image/jpeg,image/x-icon,.ico" onchange={(event) => onpickicon?.(event)} /></label>{/if}{#if iconPreview && onremoveicon}<button disabled={!!busy} onclick={() => perform('remove-logo', () => onremoveicon?.(), 'Logo predeterminado restaurado')}><UiIcon name="trash" size={15}/>{$t('Quitar logo')}</button>{/if}</div></div></div>{#if iconMessage}<small role="status">{iconMessage}</small>{/if}</section></div>
  {:else if tab === 'minecraft'}
    <div class="two-columns"><section class="surface"><h3><UiIcon name="cube" />{$t('Ventana del juego')}</h3><label for="game-resolution">{$t('Resolución predeterminada')}</label><select id="game-resolution" value={`${settings.resolution_width}x${settings.resolution_height}`} onchange={(event) => { const [resolution_width, resolution_height] = event.currentTarget.value.split('x').map(Number); void change({ resolution_width, resolution_height }); }}>{#each [[854, 480], [1280, 720], [1920, 1080]] as [width, height]}<option value={`${width}x${height}`}>{width} × {height}</option>{/each}{#if !['854x480','1280x720','1920x1080'].includes(`${settings.resolution_width}x${settings.resolution_height}`)}<option value={`${settings.resolution_width}x${settings.resolution_height}`}>{settings.resolution_width} × {settings.resolution_height}</option>{/if}</select><div class="setting-row"><strong>{$t('Iniciar en pantalla completa')}</strong><label class="toggle"><input type="checkbox" checked={settings.fullscreen} onchange={(event) => change({ fullscreen: event.currentTarget.checked })} aria-label={$t('Iniciar en pantalla completa')} /><span></span></label></div></section><section class="surface"><h3><UiIcon name="chip"/>{$t('Memoria global')}</h3><div class="memory-number">{settings.ram_gb}<span>GB</span></div><input type="range" min="1" max={memoryLimit} step="1" value={settings.ram_gb} oninput={(event) => change({ ram_gb: +event.currentTarget.value })} aria-label={$t('Memoria global')} /><small>{$t('Memoria del equipo')}: {totalMemoryGb.toFixed(1)} GB</small></section></div><section class="surface"><h3><GameIcon name="compass" size={19}/>{$t('Accesos rápidos')}</h3><div class="actions">{#each [{ id: 'root' as const, name: 'Carpeta del juego' }, { id: 'saves' as const, name: 'Mundos' }, { id: 'screenshots' as const, name: 'Capturas' }, { id: 'resourcepacks' as const, name: 'Resourcepacks' }, { id: 'shaderpacks' as const, name: 'Shaderpacks' }] as folder}<button onclick={() => perform(folder.id, () => onopenfolder(folder.id), 'Listo')}><UiIcon name="folder" size={16} />{$t(folder.name)}</button>{/each}</div></section>
  {:else if tab === 'java'}
    <section class="surface" id="java-manager"><div class="section-title"><div><h3><UiIcon name="java" />{$t('Motores Java')}</h3><p>{$t('El launcher selecciona un runtime compatible según el manifiesto de cada versión.')}</p></div><button disabled={!!busy} onclick={() => perform('scan', onscanjava, 'Listo')}><UiIcon name="refresh" size={16} />{$t(busy === 'scan' ? 'Escaneando…' : 'Detectar Java')}</button></div><div class="runtime-list">{#each runtimeRows as runtime}<article class="runtime"><div class="java-badge" data-no-translate><JavaRuntimeIcon major={runtime.major}/></div><div class="runtime-info"><strong>{runtime.major === 0 ? $t('Java del sistema') : `Java ${runtime.major}`}</strong><small class:available={runtime.installed}>{$t(runtime.installed ? 'Disponible' : 'No instalado')}</small>{#if runtime.path}<code data-no-translate title={runtime.path}>{runtime.path}</code>{/if}</div><div class="runtime-actions">{#if runtime.installed}<button disabled={!!busy} title={$t('Probar ejecutable Java')} onclick={() => perform(`test-${runtime.major}`, () => ontestjava(runtime.path), 'Correcto')}><UiIcon name="play" size={15} />{$t('Probar')}</button>{:else}<button disabled={!!busy} onclick={() => perform(`install-${runtime.major}`, () => oninstalljava(runtime.major), 'Listo')}><UiIcon name="download" size={15} />{$t(busy === `install-${runtime.major}` ? 'Preparando…' : 'Descargar runtime')}</button>{/if}{#if runtime.major !== 0}<label class="toggle"><input type="checkbox" checked={runtime.enabled} disabled={!!busy} onchange={(event) => { const enabled = event.currentTarget.checked; void perform(`toggle-${runtime.major}`, () => ontogglejava(runtime.major, enabled)); }} aria-label={`${runtime.enabled ? $t('Desactivar') : $t('Activar')} Java ${runtime.major}`} /><span></span></label>{/if}</div></article>{/each}</div></section><section class="surface"><h3><UiIcon name="java"/>{$t('Probar ejecutable Java')}</h3><label for="java-path">{$t('Ruta de Java')}</label><div class="input-actions"><input id="java-path" bind:value={javaPath} placeholder="C:\Program Files\Java\bin\java.exe" spellcheck="false" data-no-translate /><button disabled={!!busy || !javaPath.trim()} onclick={() => perform('java-test', () => ontestjava(javaPath.trim()), 'Correcto')}><UiIcon name="play" size={16} />{$t('Probar')}</button></div></section>
  {:else if tab === 'accounts'}
    <section class="surface"><div class="section-title"><div><h3><UiIcon name="user" />{$t('Cuentas')}</h3><p>{$t('Las credenciales se guardan de forma segura en este dispositivo.')}</p></div><div class="actions"><button class="primary" disabled={!!busy} onclick={() => perform('microsoft', onaddmicrosoft, 'Listo')}><ServiceLogo name="microsoft" size={17}/>{$t('Añadir cuenta Microsoft')}</button><button disabled={!!busy||!offlineAllowed} title={offlineMessage} onclick={() => addOffline = !addOffline}><UiIcon name="plus" size={15}/>{$t('Añadir perfil Offline')}</button></div></div><p class="offline-eligibility" role="status">{offlineMessage}</p>{#if addOffline&&offlineAllowed}<form class="offline-form" onsubmit={(event) => { event.preventDefault(); void createOffline(); }}><label for="offline-name">{$t('Nombre de jugador')}</label><div class="input-actions"><input id="offline-name" bind:value={offlineName} maxlength="16" pattern={'[A-Za-z0-9_]{3,16}'} required placeholder="Steve" spellcheck="false" data-no-translate /><button type="submit" disabled={!!busy}><UiIcon name="plus" size={15}/>{$t('Añadir')}</button><button type="button" onclick={() => addOffline = false}><UiIcon name="close" size={15}/>{$t('Cancelar')}</button></div><small>{$t('Las cuentas Offline no autentican una licencia de Minecraft.')}</small></form>{/if}<div class="account-grid">{#each accounts as account}<article class="account-card" class:active={account.active}><div class="account-heading">{#if account.avatar_url}<img src={account.avatar_url} alt="" />{:else}<div class="avatar-placeholder">{#if account.kind === 'microsoft'}<ServiceLogo name="microsoft" size={25}/>{:else}<UiIcon name="user" size={25}/>{/if}</div>{/if}<div><strong data-no-translate>{account.name}</strong><small class="account-kind">{#if account.kind === 'microsoft'}<ServiceLogo name="microsoft" size={12}/>{:else}<UiIcon name="user" size={12}/>{/if}{$t(account.kind === 'microsoft' ? 'Microsoft Premium' : 'Offline')}</small></div>{#if account.active}<span class="active-badge">{$t('Cuenta activa')}</span>{/if}</div><p>{account.status ? $t(account.status) : $t(account.kind === 'microsoft' ? 'Sesión guardada' : 'Modo Offline')}</p><div class="account-actions"><button class:primary={!account.active} disabled={!!busy || account.active||(account.kind==='offline'&&!offlineAllowed)} onclick={() => perform(`activate-${account.id}`, () => onactivateaccount(account.id))}><UiIcon name={account.active?"check":"user"} size={14}/>{$t(account.active ? 'Activado' : 'Activar cuenta')}</button><button class="icon-button danger" title={$t('Eliminar cuenta')} aria-label={`${$t('Eliminar cuenta')}: ${account.name}`} onclick={() => removeId = account.id}><UiIcon name="close" size={16} /></button></div>{#if removeId === account.id}<div class="remove-confirm"><small>{$t('Quitar esta cuenta del dispositivo')}</small><div class="actions"><button class="danger" disabled={!!busy} onclick={() => perform(`remove-${account.id}`, async () => { await onremoveaccount(account.id); removeId = ''; })}><UiIcon name="trash" size={15}/>{$t('Eliminar')}</button><button onclick={() => removeId = ''}><UiIcon name="close" size={15}/>{$t('Cancelar')}</button></div></div>{/if}</article>{/each}</div>{#if !accounts.length}<div class="empty"><UiIcon name="user" size={36} /><h4>{$t('Sin cuentas guardadas')}</h4><p>{$t('Elige una cuenta para esta sesión.')}</p></div>{/if}</section>
  {/if}

</section>

<style>
